import * as net from 'net';
import * as os from 'os';
import { EventEmitter } from 'events';

interface DeviceConfig {
  deviceId: string;
  smtpHost: string;
  smtpPort: number;
  alertRecipient: string;
  firmwareVersion: string;
}

class HeaderEncoder {
  private static readonly SAFE_CHARS = /^[\x20-\x7E]*$/;

  static encodeValue(value: string): string {
    // RFC 2047 Q-encoding for non-ASCII
    if (!this.SAFE_CHARS.test(value)) {
      return `=?UTF-8?Q?${this.qEncode(value)}?=`;
    }
    return value;
  }

  private static qEncode(input: string): string {
    return Buffer.from(input, 'utf-8')
      .toString('hex')
      .replace(/../g, '=$&')
      .toUpperCase();
  }

  static sanitizeHeaderName(name: string): string {
    return name.replace(/[^a-zA-Z0-9\-]/g, '');
  }

  static foldHeader(name: string, value: string): string {
    const line = `${name}: ${value}`;
    if (line.length <= 998) return line;
    // RFC 5322 folding
    const chunks: string[] = [];
    for (let i = 0; i < line.length; i += 76) {
      chunks.push(line.substring(i, i + 76));
    }
    return chunks.join('\r\n ');
  }
}

class AlertMailer {
  private config: DeviceConfig;
  private pendingAlerts: Array<{ subject: string; body: string; metadata: Record<string, string> }> = [];

  constructor(config: DeviceConfig) {
    this.config = config;
  }

  queueAlert(subject: string, body: string, metadata: Record<string, string> = {}): void {
    this.pendingAlerts.push({ subject, body, metadata });
  }

  private buildHeaders(alert: { subject: string; body: string; metadata: Record<string, string> }): string[] {
    const headers: string[] = [];
    const timestamp = new Date().toUTCString();

    headers.push(HeaderEncoder.foldHeader('From', `device-${this.config.deviceId}@iot.local`));
    headers.push(HeaderEncoder.foldHeader('To', this.config.alertRecipient));
    headers.push(HeaderEncoder.foldHeader('Date', timestamp));
    headers.push(HeaderEncoder.foldHeader('Subject', HeaderEncoder.encodeValue(alert.subject)));
    headers.push(HeaderEncoder.foldHeader('X-Device-ID', this.config.deviceId));
    headers.push(HeaderEncoder.foldHeader('X-Firmware', this.config.firmwareVersion));
    headers.push(HeaderEncoder.foldHeader('MIME-Version', '1.0'));
    headers.push(HeaderEncoder.foldHeader('Content-Type', 'text/plain; charset=utf-8'));

    // Append custom metadata headers
    for (const [key, value] of Object.entries(alert.metadata)) {
      const safeName = HeaderEncoder.sanitizeHeaderName(`X-Meta-${key}`);
      headers.push(HeaderEncoder.foldHeader(safeName, this.normalizeFieldValue(value)));
    }

    return headers;
  }

  private normalizeFieldValue(value: string): string {
    // Normalize unicode and strip ALL control characters including CR/LF
    const normalized = value.normalize('NFC');
    return normalized.replace(/[\x00-\x1F\x7F]/g, '');
  }

  async flush(): Promise<void> {
    for (const alert of this.pendingAlerts) {
      await this.sendSmtp(alert);
    }
    this.pendingAlerts = [];
  }

  private sendSmtp(alert: { subject: string; body: string; metadata: Record<string, string> }): Promise<void> {
    return new Promise((resolve, reject) => {
      const socket = net.createConnection(this.config.smtpPort, this.config.smtpHost);
      const headers = this.buildHeaders(alert);
      const message = headers.join('\r\n') + '\r\n\r\n' + alert.body;

      socket.on('connect', () => {
        socket.write(`EHLO ${os.hostname()}\r\n`);
        socket.write(`MAIL FROM:<device-${this.config.deviceId}@iot.local>\r\n`);
        socket.write(`RCPT TO:<${this.config.alertRecipient}>\r\n`);
        socket.write('DATA\r\n');
        socket.write(message + '\r\n.\r\n');
        socket.write('QUIT\r\n');
        socket.end();
        resolve();
      });

      socket.on('error', reject);
      socket.setTimeout(5000, () => { socket.destroy(); reject(new Error('timeout')); });
    });
  }
}

class FirmwareRuntime extends EventEmitter {
  private mailer: AlertMailer;
  private shutdownInProgress = false;
  private sensorData: Map<string, string> = new Map();

  constructor(config: DeviceConfig) {
    super();
    this.mailer = new AlertMailer(config);
    this.setupShutdownHandlers();
  }

  private setupShutdownHandlers(): void {
    const shutdown = async (signal: string) => {
      if (this.shutdownInProgress) return;
      this.shutdownInProgress = true;

      // Send final telemetry with last sensor readings as metadata
      const metadata: Record<string, string> = {};
      for (const [sensor, reading] of this.sensorData.entries()) {
        metadata[sensor] = reading;
      }

      this.mailer.queueAlert(
        `Device shutdown: ${signal}`,
        `Graceful shutdown initiated by ${signal}`,
        metadata
      );

      await this.mailer.flush();
      process.exit(0);
    };

    process.on('SIGTERM', () => shutdown('SIGTERM'));
    process.on('SIGINT', () => shutdown('SIGINT'));
  }

  updateSensor(sensorId: string, value: string): void {
    this.sensorData.set(sensorId, value);

    if (this.isAnomalous(value)) {
      this.mailer.queueAlert(
        `Anomaly detected on sensor ${sensorId}`,
        `Sensor ${sensorId} reported anomalous value: ${value}`,
        { [sensorId]: value, timestamp: Date.now().toString() }
      );
    }
  }

  private isAnomalous(value: string): boolean {
    const num = parseFloat(value);
    return !isNaN(num) && (num > 100 || num < -50);
  }
}

// Device initialization
const config: DeviceConfig = {
  deviceId: process.env.DEVICE_ID || 'iot-001',
  smtpHost: process.env.SMTP_HOST || 'localhost',
  smtpPort: parseInt(process.env.SMTP_PORT || '25'),
  alertRecipient: process.env.ALERT_RECIPIENT || 'admin@example.com',
  firmwareVersion: '2.4.1'
};

const runtime = new FirmwareRuntime(config);

// Simulated sensor input loop (in real firmware, this reads GPIO/I2C)
const server = net.createServer((conn) => {
  conn.on('data', (data) => {
    const msg = data.toString().trim();
    const [sensorId, ...valueParts] = msg.split(':');
    if (sensorId && valueParts.length > 0) {
      runtime.updateSensor(sensorId, valueParts.join(':'));
    }
  });
});

server.listen(9100, '127.0.0.1');
